#!/usr/bin/env node
'use strict';

var fs = require('fs');
var promises = require('fs/promises');
var path = require('path');
var child_process = require('child_process');

const PREFIX = '[capacitor-electron]';
const logInfo = (message) => {
    console.log(`${PREFIX} ${message}`);
};
const logWarn = (message) => {
    console.warn(`${PREFIX} WARN: ${message}`);
};
const fail = (message) => {
    console.error(`${PREFIX} ERROR: ${message}`);
    process.exit(1);
};

const TEXT_EXTENSIONS = ['.ts', '.js', '.json', '.md', '.html'];
const slugify = (value) => value
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'app';
async function addCommand(context) {
    if (fs.existsSync(context.platformDir)) {
        fail(`${context.platformDir} already exists. Delete it first if you want to re-add the electron platform.`);
    }
    const templatesDir = path.join(__dirname, '../../templates/scaffold');
    const variables = {
        APP_ID: context.config.appId ?? 'com.example.app',
        APP_NAME: context.config.appName ?? 'App',
        APP_NAME_SLUG: slugify(context.config.appName ?? 'app'),
    };
    await copyTemplates(templatesDir, context.platformDir, variables);
    logInfo(`Created ${context.platformDir}.`);
    logInfo('Next steps:');
    logInfo('  1. cd electron && npm install');
    logInfo('  2. npx cap sync @capawesome/capacitor-electron');
    logInfo('  3. npx cap run @capawesome/capacitor-electron');
}
async function copyTemplates(sourceDir, targetDir, variables) {
    await promises.mkdir(targetDir, { recursive: true });
    const entries = await promises.readdir(sourceDir, { withFileTypes: true });
    for (const entry of entries) {
        const sourcePath = path.join(sourceDir, entry.name);
        // npm strips `.gitignore` files from published packages, so templates
        // ship them with a `gitignore` name.
        const targetName = entry.name === 'gitignore' ? '.gitignore' : entry.name;
        const targetPath = path.join(targetDir, targetName);
        if (entry.isDirectory()) {
            await copyTemplates(sourcePath, targetPath, variables);
        }
        else if (TEXT_EXTENSIONS.some(extension => entry.name.endsWith(extension)) ||
            entry.name === 'gitignore') {
            const content = await promises.readFile(sourcePath, 'utf8');
            await promises.writeFile(targetPath, substitute(content, entry.name, variables));
        }
        else {
            await promises.cp(sourcePath, targetPath);
        }
    }
}
/**
 * Replaces the `{{NAME}}` placeholders of a template file, escaping the values
 * for the file type so that e.g. an app name with quotes keeps the file valid.
 */
const substitute = (content, fileName, variables) => {
    const escape = escaperFor(fileName);
    return content.replace(/{{(\w+)}}/g, (match, name) => name in variables ? escape(variables[name]) : match);
};
const escaperFor = (fileName) => {
    if (fileName.endsWith('.json')) {
        return escapeJsonString;
    }
    if (fileName.endsWith('.js') || fileName.endsWith('.ts')) {
        // Templates use single-quoted string literals.
        return value => escapeJsonString(value).replace(/'/g, "\\'");
    }
    if (fileName.endsWith('.html')) {
        return escapeHtml;
    }
    return value => value;
};
const escapeJsonString = (value) => JSON.stringify(value).slice(1, -1);
const escapeHtml = (value) => value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

function readCliContext() {
    const rootDir = process.env.CAPACITOR_ROOT_DIR;
    if (!rootDir) {
        return fail('CAPACITOR_ROOT_DIR is not set. This command must be invoked by the Capacitor CLI, e.g. `npx cap sync @capawesome/capacitor-electron`.');
    }
    const webDir = process.env.CAPACITOR_WEB_DIR ?? '';
    let config = {};
    const rawConfig = process.env.CAPACITOR_CONFIG;
    if (rawConfig) {
        try {
            config = JSON.parse(rawConfig);
        }
        catch {
            return fail('CAPACITOR_CONFIG contains invalid JSON.');
        }
    }
    const platformDir = path.join(rootDir, 'electron');
    return {
        rootDir,
        webDir,
        config,
        platformDir,
        generatedDir: path.join(platformDir, 'generated'),
        appDir: path.join(platformDir, 'app'),
    };
}
function requirePlatformDir(context) {
    if (!fs.existsSync(context.platformDir)) {
        fail(`No electron platform found at ${context.platformDir}. Run \`npx cap add @capawesome/capacitor-electron\` first.`);
    }
}

async function copyCommand(context) {
    requirePlatformDir(context);
    await embedConfig(context);
    if (!context.webDir || !fs.existsSync(context.webDir)) {
        fail(`Web assets directory ${context.webDir || '(unset)'} does not exist. Build your web app first.`);
    }
    await promises.rm(context.appDir, { recursive: true, force: true });
    await promises.cp(context.webDir, context.appDir, { recursive: true });
    logInfo(`Copied web assets to ${context.appDir}.`);
}
async function embedConfig(context) {
    await promises.mkdir(context.generatedDir, { recursive: true });
    await promises.writeFile(path.join(context.generatedDir, 'capacitor.config.json'), `${JSON.stringify(context.config, null, 2)}\n`);
}

/**
 * The directory (relative to the package root) holding a plugin's electron
 * implementation, or `undefined` when the package declares none. Like the
 * Capacitor CLI for `android`/`ios`, the presence of the platform key marks
 * an implementation and `src` defaults to the platform name.
 */
const getElectronSrc = (packageJson) => packageJson.capacitor?.electron
    ? (packageJson.capacitor.electron.src ?? 'electron')
    : undefined;

async function updateCommand(context) {
    requirePlatformDir(context);
    await embedConfig(context);
    const manifest = await generatePluginManifest(context);
    await promises.mkdir(context.generatedDir, { recursive: true });
    await promises.writeFile(path.join(context.generatedDir, 'plugin-manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
    await promises.writeFile(path.join(context.generatedDir, 'plugins.mjs'), renderRegistrar(manifest));
    logInfo(`Found ${manifest.plugins.length} plugin(s) with an electron implementation.`);
}
/**
 * Statically scans the app's dependencies for `capacitor.electron` entries.
 * No plugin code is executed; classes and methods are enumerated at boot,
 * inside Electron.
 */
async function generatePluginManifest(context) {
    const rootPackageJson = JSON.parse(await promises.readFile(path.join(context.rootDir, 'package.json'), 'utf8'));
    const dependencyNames = [
        ...Object.keys(rootPackageJson.dependencies ?? {}),
        ...Object.keys(rootPackageJson.devDependencies ?? {}),
    ];
    const plugins = [];
    for (const dependencyName of dependencyNames) {
        const plugin = scanDependency(context, dependencyName);
        if (plugin) {
            plugins.push(plugin);
        }
    }
    plugins.sort((a, b) => a.packageName.localeCompare(b.packageName));
    return { platformVersion: platformVersion(), plugins };
}
function scanDependency(context, dependencyName) {
    const packageDir = path.join(context.rootDir, 'node_modules', dependencyName);
    const packageJsonPath = path.join(packageDir, 'package.json');
    if (!fs.existsSync(packageJsonPath)) {
        return null;
    }
    const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
    const electronSrc = getElectronSrc(packageJson);
    if (!electronSrc) {
        return null;
    }
    const entryPath = path.join(packageDir, electronSrc, 'dist', 'plugin.mjs');
    if (!fs.existsSync(entryPath)) {
        logWarn(`${dependencyName} declares an electron implementation but ${entryPath} does not exist (the implementation must be an ES module at <src>/dist/plugin.mjs). Skipping.`);
        return null;
    }
    return {
        packageName: dependencyName,
        specifier: `${dependencyName}/${electronSrc}/dist/plugin.mjs`,
    };
}
const platformVersion = () => JSON.parse(fs.readFileSync(path.join(__dirname, '../../package.json'), 'utf8')).version;
function renderRegistrar(manifest) {
    const entries = manifest.plugins
        .map(plugin => `  '${plugin.packageName}': () => import('${plugin.specifier}'),`)
        .join('\n');
    return [
        '/* eslint-disable */',
        '// Generated by @capawesome/capacitor-electron — do not edit.',
        '// Plugin modules are resolved from the app root `node_modules`.',
        'export const plugins = {',
        entries,
        '};',
        '',
    ].join('\n');
}

async function runCommand(context) {
    const devServerUrl = context.config.server?.url;
    await prepare(context, { requireWebAssets: !devServerUrl });
    if (devServerUrl) {
        await assertDevServerReachable(devServerUrl);
        logInfo(`Using dev server at ${devServerUrl}.`);
    }
    await launchElectron(context, devServerUrl);
}
async function assertDevServerReachable(devServerUrl) {
    try {
        await fetch(devServerUrl, { signal: AbortSignal.timeout(3000) });
    }
    catch {
        fail(`The dev server configured in the Capacitor config (server.url = ${devServerUrl}) is not reachable. Start it first, or remove server.url to serve the built web assets instead.`);
    }
}
async function openCommand(context) {
    await prepare(context, { requireWebAssets: true });
    await launchElectron(context, undefined);
}
async function prepare(context, options) {
    requirePlatformDir(context);
    if (options.requireWebAssets) {
        await copyCommand(context);
    }
    await updateCommand(context);
    await runInPlatformDir(context, 'npx tsc', 'Compiling electron/main.ts');
}
async function launchElectron(context, devServerUrl) {
    if (!fs.existsSync(`${context.platformDir}/node_modules`)) {
        fail(`Dependencies are not installed in ${context.platformDir}. Run \`npm install\` there first.`);
    }
    await runInPlatformDir(context, 'npx electron .', 'Launching Electron', {
        ...(devServerUrl
            ? { CAPACITOR_ELECTRON_DEV_SERVER_URL: devServerUrl }
            : {}),
    });
}
function runInPlatformDir(context, command, description, env = {}) {
    logInfo(`${description}...`);
    return new Promise((resolve, reject) => {
        const child = child_process.spawn(command, {
            cwd: context.platformDir,
            shell: true,
            stdio: 'inherit',
            env: { ...process.env, ...env },
        });
        child.on('close', code => {
            if (code === 0) {
                resolve();
            }
            else {
                reject(new Error(`\`${command}\` failed with exit code ${code ?? 'null'}.`));
            }
        });
        child.on('error', reject);
    });
}

/**
 * Never vendored: provided by the Electron runtime / the packaging tool.
 */
const EXCLUDED_PACKAGES = new Set(['electron']);
const PLATFORM_PACKAGE_NAME = '@capawesome/capacitor-electron';
/**
 * Prepares the user-owned `electron/` project for packaging. electron-builder
 * only includes files inside the project, but at runtime the platform and the
 * plugins are resolved from the app root `node_modules`. This command copies
 * them — plus their production, peer, and installed optional dependency
 * closure — into
 * `electron/vendor/node_modules`, which the scaffolded electron-builder
 * config maps to `node_modules` inside the packaged app, so the exact same
 * module resolution works there.
 *
 * Runs with cwd = the `electron/` directory (via the scaffolded `pack`
 * script); needs no Capacitor CLI environment.
 */
function vendorCommand() {
    const electronDir = process.cwd();
    const rootDir = path.dirname(electronDir);
    const manifestPath = path.join(electronDir, 'generated', 'plugin-manifest.json');
    if (!fs.existsSync(manifestPath)) {
        fail(`${manifestPath} is missing. Run \`npx cap sync ${PLATFORM_PACKAGE_NAME}\` first.`);
    }
    const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
    const vendorRoot = path.join(electronDir, 'vendor', 'node_modules');
    fs.rmSync(path.join(electronDir, 'vendor'), { recursive: true, force: true });
    fs.mkdirSync(vendorRoot, { recursive: true });
    const vendored = new Map();
    const nativePackages = new Set();
    // The platform runtime itself (only what the packaged app executes).
    const platformDir = path.join(__dirname, '..', '..');
    vendorSubset(platformDir, path.join(vendorRoot, PLATFORM_PACKAGE_NAME), [
        'package.json',
        'LICENSE',
        'dist',
    ]);
    vendored.set(PLATFORM_PACKAGE_NAME, {
        version: readPackageJson(platformDir).version,
        vendorDir: path.join(vendorRoot, PLATFORM_PACKAGE_NAME),
    });
    for (const plugin of manifest.plugins) {
        const packageDir = findPackageDir(rootDir, plugin.packageName);
        if (!packageDir) {
            return fail(`${plugin.packageName} is not installed in ${rootDir}. Run \`npm install\` and \`npx cap sync ${PLATFORM_PACKAGE_NAME}\` first.`);
        }
        const packageJson = readPackageJson(packageDir);
        const electronSrc = getElectronSrc(packageJson);
        if (!electronSrc) {
            return fail(`${plugin.packageName} does not declare \`capacitor.electron\`. Run \`npx cap sync ${PLATFORM_PACKAGE_NAME}\` again.`);
        }
        const vendorDir = path.join(vendorRoot, plugin.packageName);
        // A plugin's electron implementation is a self-contained bundle; only
        // the bundle and the package manifest are needed.
        vendorSubset(packageDir, vendorDir, [
            'package.json',
            'LICENSE',
            path.join(electronSrc, 'dist'),
        ]);
        vendored.set(plugin.packageName, {
            version: packageJson.version,
            vendorDir,
        });
        vendorDependencyClosure(packageDir, packageJson, vendorDir, vendorRoot, vendored, nativePackages);
    }
    logInfo(`Vendored ${vendored.size} package(s) into ${path.join(electronDir, 'vendor')}.`);
    if (nativePackages.size > 0) {
        logWarn(`Native Node modules detected (${[...nativePackages].join(', ')}). ` +
            'They must be rebuilt against the Electron ABI before packaging (e.g. with @electron/rebuild); automatic rebuilding of vendored plugin dependencies is not performed yet.');
    }
}
function vendorDependencyClosure(dependentDir, dependentPackageJson, dependentVendorDir, vendorRoot, vendored, nativePackages) {
    const dependencies = {
        ...dependentPackageJson.optionalDependencies,
        ...dependentPackageJson.peerDependencies,
        ...dependentPackageJson.dependencies,
    };
    for (const dependencyName of Object.keys(dependencies)) {
        if (EXCLUDED_PACKAGES.has(dependencyName) ||
            dependencyName === PLATFORM_PACKAGE_NAME) {
            continue;
        }
        const dependencyDir = findPackageDir(dependentDir, dependencyName);
        if (!dependencyDir) {
            const optional = dependentPackageJson.optionalDependencies?.[dependencyName] !==
                undefined ||
                dependentPackageJson.peerDependencies?.[dependencyName] !== undefined;
            if (optional) {
                continue;
            }
            return fail(`Cannot resolve dependency ${dependencyName} of ${dependentPackageJson.name}.`);
        }
        const dependencyPackageJson = readPackageJson(dependencyDir);
        const existing = vendored.get(dependencyName);
        if (existing && existing.version === dependencyPackageJson.version) {
            continue;
        }
        // First occurrence goes to the top level; a conflicting version nests
        // under its dependent, matching Node resolution semantics.
        const vendorDir = existing
            ? path.join(dependentVendorDir, 'node_modules', dependencyName)
            : path.join(vendorRoot, dependencyName);
        fs.cpSync(dependencyDir, vendorDir, {
            recursive: true,
            dereference: true,
            // Nested node_modules are handled by the closure walk itself.
            filter: source => !path.relative(dependencyDir, source)
                .split(/[\\/]/)
                .includes('node_modules'),
        });
        if (!existing) {
            vendored.set(dependencyName, {
                version: dependencyPackageJson.version,
                vendorDir,
            });
        }
        if (fs.existsSync(path.join(dependencyDir, 'binding.gyp')) ||
            fs.existsSync(path.join(dependencyDir, 'prebuilds'))) {
            nativePackages.add(dependencyName);
        }
        vendorDependencyClosure(dependencyDir, dependencyPackageJson, vendorDir, vendorRoot, vendored, nativePackages);
    }
}
function vendorSubset(sourceDir, targetDir, entries) {
    fs.mkdirSync(targetDir, { recursive: true });
    for (const entry of entries) {
        const sourcePath = path.join(sourceDir, entry);
        if (fs.existsSync(sourcePath)) {
            fs.cpSync(sourcePath, path.join(targetDir, entry), {
                recursive: true,
                dereference: true,
            });
        }
    }
}
/**
 * Node's module resolution for bare specifiers, without touching `exports`
 * maps: walk `node_modules` directories from `fromDir` upwards.
 */
function findPackageDir(fromDir, packageName) {
    let currentDir = fromDir;
    for (;;) {
        const candidate = path.join(currentDir, 'node_modules', packageName);
        if (fs.existsSync(path.join(candidate, 'package.json'))) {
            return candidate;
        }
        const parentDir = path.dirname(currentDir);
        if (parentDir === currentDir) {
            return null;
        }
        currentDir = parentDir;
    }
}
const readPackageJson = (packageDir) => JSON.parse(fs.readFileSync(path.join(packageDir, 'package.json'), 'utf8'));

async function main() {
    const [, , command] = process.argv;
    if (command === 'vendor') {
        // Invoked from the scaffolded `pack` script (cwd = electron/); needs no
        // Capacitor CLI environment.
        vendorCommand();
        return;
    }
    const context = readCliContext();
    switch (command) {
        case 'add':
            return addCommand(context);
        case 'copy':
            return copyCommand(context);
        case 'update':
            return updateCommand(context);
        case 'open':
            return openCommand(context);
        case 'run':
            return runCommand(context);
        default:
            fail(`Unknown command: ${command ?? '(none)'}`);
    }
}
main().catch(error => {
    fail(error instanceof Error ? error.message : String(error));
});
